using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.IO;
using System.Web.Script.Serialization;
using ShatteredSail.Core.Gameplay;
partial class Program {
static string outputRoot;static CoreVoyageSession s;static List<object> rows=new List<object>();static StreamWriter actions;
static void Need(bool ok,string why){if(!ok)throw new Exception(why);}
static int Ix(string id)=>Enumerable.Range(0,CoreVoyageSession.CardLibrary.Count).Single(i=>CoreVoyageSession.CardLibrary[i].Id==id);
static void SetDeck(NavalBattleStage st,string[] ids){Need(s.SetBattleDeck(st,ids.Select(Ix).ToArray()),"deck "+st);}
static void Setup(string seed){s=new CoreVoyageSession();s.RestoreTreasureProgress(new CoreTreasureProgress{pirateExperience=5400});Need(s.RestoreCardPackProgress(null,10),"owned");Need(s.SelectShip(7),"ship");s.SelectRoute(2);s.SetSeed(seed);s.ConfigureDepartureCrew(28,0);s.ConfigureCrewCapabilities(false,false,false,false,false,false);s.ConfigureSpecialCardSources(new string[0],new string[0]);s.ConfigureComponentBonuses(0,0,0,0,0);s.ConfigureBattleEquipment(1,1);s.RestoreProfile(10000000,s.CurrentPort);
var prep=new[]{"card_school_arcane_b02","card_school_arcane_b02","card_school_arcane_b01","card_school_arcane_b01","card_energy_order","card_energy_order","card_tactical_draw","card_tactical_draw","card_emergency_repair","card_emergency_repair"};
var naval=new[]{"card_school_arcane_n06","card_school_arcane_n06","card_school_arcane_n07","card_school_arcane_n07","card_school_arcane_b06","card_school_arcane_b06","card_energy_order","card_energy_order","card_tactical_draw","card_tactical_draw","card_emergency_repair","card_emergency_repair"};
SetDeck(NavalBattleStage.Preparation,prep);SetDeck(NavalBattleStage.Naval,naval);foreach(var id in prep.Concat(naval).Distinct()){int ix=Ix(id);while(s.GetCardUpgradeCost(ix)>0)Need(s.TryUpgradeBattleCard(ix,out string reason),reason);}
s.Cargo.Water=s.Cargo.Food=s.Cargo.Beer=s.Cargo.Iron=s.Cargo.Cloth=0;s.Cargo.Powder=20;s.Cargo.Cannonballs=20;s.Cargo.Wood=120;s.Cargo.Medicine=500;Need(s.Cargo.UsedVolume<=s.CargoCapacityValue,"cargo");if(seed.EndsWith("-0")){var defs=new List<string>();foreach(var stage in new[]{NavalBattleStage.Preparation,NavalBattleStage.Naval}){defs.Add(stage.ToString());foreach(var g in s.GetBattleDeck(stage).GroupBy(i=>i)){var c=s.GetBattleCard(g.Key);defs.Add(c.Id+" | "+c.Name+" | +"+s.GetCardUpgradeLevel(c.Id)+" | x"+g.Count()+" | "+c.Description.Replace("\n"," "));}}File.WriteAllLines(Path.Combine(outputRoot,"deck.txt"),defs);}s.StartVoyage();Need(s.Phase==CoreDemoPhase.Sailing,"start");}
static object State()=>new{hull=s.Hull,maxHull=s.MaxHull,powder=s.Cargo.Powder,balls=s.Cargo.Cannonballs,wood=s.Cargo.Wood,medicine=s.Cargo.Medicine,volume=s.Cargo.UsedVolume};
static double Score(int index){var b=s.Battle;var c=s.GetBattleCard(index);var e=s.GetBattleCardEffects(c,b.Stage);bool prep=b.Stage==NavalBattleStage.Preparation;int cost=s.GetBattleCardEnergyCost(index),damage=s.GetBattleCardDamage(c,b.Stage);int incoming=CoreBattleIntentPresentation.Build(s).Where(x=>x.IsAttack).Sum(x=>x.Amount??0),need=Math.Max(0,(prep?0:incoming)-b.PlayerBlock);double score=Math.Min(s.MaxHull-s.Hull,e.Repair)*(prep?8:s.Hull<100?5:1.5)+Math.Min(need,e.Block)*(s.Hull<incoming*2?3:1.0);if(c.Action==NavalBattleCardAction.Energize)return 1000; if(c.Id=="card_tactical_draw")return b.Hand.Count<7?200/(cost+.65):1;
if(prep&&c.Id=="card_school_arcane_b02")score+=70;if(prep&&c.Id=="card_school_arcane_b01")score+=c.Draw*5;
if(!prep){if(damage>=b.EnemyHull+b.EnemyBlock)return 10000/(cost+.65);score+=damage*1.7;if(c.Id=="card_school_arcane_n06")score+=Math.Max(0,8-b.Schools.Mana)*14;if(c.Id=="card_school_arcane_b06")score+=Math.Max(0,8-b.Schools.Mana)*8+c.Draw*10;}
if(c.Draw>0&&b.Hand.Count<7)score+=c.Draw*(b.Hand.Count<4?8:3);return score/(cost+.65);}
static bool Fight(CoreEncounter enc,string seed){typeof(CoreVoyageSession).GetProperty("ActiveEncounter").SetValue(s,enc);typeof(CoreVoyageSession).GetMethod("StartBattle",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(s,new object[]{enc,true});var b=s.Battle;var before=State();int turns=0,cards=0,moves=0,hullHeal=0,minHull=s.Hull;string outcome="watchdog";
for(int a=0;a<2000&&s.Phase==CoreDemoPhase.Battle&&b.Stage!=NavalBattleStage.Boarding&&turns<120;a++){int oldHull=s.Hull;string act;int best=-1;double score=.01;for(int h=0;h<b.Hand.Count;h++){if(!s.CanPlayCard(h))continue;double p=Score(b.Hand[h]);if(p>score){score=p;best=h;}}if(best>=0){act=s.GetBattleCard(b.Hand[best]).Id;Need(s.PlayCard(best),act);cards++;}else if(Move(s)){act="move";moves++;}else{Need(s.EndBattleTurn(),"end");turns++;act="end";}hullHeal+=Math.Max(0,s.Hull-oldHull);minHull=Math.Min(minHull,s.Hull);actions.WriteLine(seed+","+enc.Id+","+a+","+b.Stage+","+act+","+s.Hull+","+b.EnemyHull+","+s.Cargo.Wood+","+b.Schools.Mana+","+b.Schools.ManaLimit+","+b.Energy+","+CoreVoyageSession.NavalGridDistance(b.PlayerPositionMeters,b.EnemyPositionMeters)+","+b.PlayerBlock);}
bool won=s.Phase==CoreDemoPhase.Sailing&&b.EnemyHull<=0&&b.Stage!=NavalBattleStage.Boarding;outcome=won?"win":b.Stage==NavalBattleStage.Boarding?"forced-boarding":s.Phase==CoreDemoPhase.Settlement?"loss":"watchdog";rows.Add(new{seed,id=enc.Id,name=enc.Name,won,outcome,turns,cards,moves,hullHeal,minHull,start=before,end=State(),enemyHull=b.EnemyHull,stage=b.Stage.ToString()});Console.WriteLine(seed+" "+enc.Name+" "+outcome+" hull="+s.Hull+" enemy="+b.EnemyHull+" wood="+s.Cargo.Wood+" turns="+turns);return won;}
static void Main(string[] args){outputRoot=args[0];Directory.CreateDirectory(outputRoot);actions=new StreamWriter(Path.Combine(outputRoot,"actions.csv"));actions.WriteLine("seed,boss,actionIndex,stage,action,hull,enemyHull,wood,mana,manaLimit,energy,distance,block");int runs=args.Length>1?int.Parse(args[1]):1;int won=0;var runSummary=new List<object>();for(int run=0;run<runs;run++){int passed=0;string seed="NAVAL-ENDURANCE-20261104-"+run;Setup(seed);foreach(var enc in CoreRouteBossCatalog.All.Select(x=>x.CreateEncounter()).Concat(new[]{CoreLegendaryWarships.CreateTreasureEncounter()}).Concat(CoreLegendaryWarships.All.Select(x=>x.CreateEncounter()))){if(!Fight(enc,seed))break;passed++;}if(passed==13)won++;runSummary.Add(new{seed,passed,end=State()});}actions.Dispose();File.WriteAllText(Path.Combine(outputRoot,"results.json"),new JavaScriptSerializer{MaxJsonLength=int.MaxValue}.Serialize(new{runs,won,runSummary,rows}));}
}
